const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=(s,n=8)=>s?`${s.slice(0,n)}…${s.slice(-6)}`:'';
const fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n);
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const money2=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const external=(url,label,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}${icon('external')}</a>`;
const field=(label,control,hint='')=>`<label class="field"><span>${label}</span>${control}${hint?`<small>${hint}</small>`:''}</label>`;
const toggle=(key,title,description,ic='shield')=>`<label class="rule-row"><span class="rule-icon">${icon(ic)}</span><span class="rule-text"><strong>${title}</strong><small>${description}</small></span><input type="checkbox" role="switch" data-design="${key}" ${state.design[key]?'checked':''}><span class="toggle" aria-hidden="true"></span></label>`;
const pill=(text,cls='')=>`<span class="pill ${cls}">${text}</span>`;
const navItems=[['studio','grid','Token studio'],['learn','book','Learn CIP-113'],['realfi','chart','RealFi lab'],['midnight','moon','Midnight privacy'],['network','globe','Network explorer'],['guide','code','Build guide']];
let initial={design:fromTemplate(),network:'preview'};
try{const saved=localStorage.getItem('prism-design-v1');if(saved)initial=parseManifest(saved);}catch{/* An invalid or unavailable saved draft never blocks startup. */}
const state={...initial,route:'studio',tab:'design',wallet:null,midnight:null,simulation:null,seqPreset:'distribution',seqMode:'preset',seqCustom:null,seqResult:null,subPreset:null,subResult:null,seizurePreset:'lawful',seizureResult:null,scenario:{amount:'250',recipient:'approved'},tip:null,tipError:'',reference:null,referenceError:'',asset:null,assetQueried:false,assetLoading:false,assetError:'',saving:true,requestId:0,registry:null,registryError:'',deployment:null,deploymentError:'',deploymentLoading:false,credit:{principal:50000,rate:8,months:12,collateral:80000,advance:70},eligibility:{score:78,minimum:65,age:28,adult:true,region:true,approved:true},eligibilityResult:null};

function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4300);}
function save(){try{const errors=validateDesign(state.design);if(!errors.length)localStorage.setItem('prism-design-v1',JSON.stringify(makeManifest(state.design,state.network)));state.saving=true;}catch{state.saving=false;}updateSave();}
function updateSave(){const el=$('#save-status');if(el)el.textContent=validateDesign(state.design).length?'Unsaved changes · check fields':state.saving?'Draft saved on this device':'Storage unavailable · export to save';}
function shell(){
  $('#app').innerHTML=`<aside class="sidebar" id="sidebar"><a class="brand" href="#studio" aria-label="PRISM home"><img src="./favicon.svg" alt="" width="38" height="38"><span>PRISM<small>CARDANO STUDIO</small></span></a><div class="sidebar-label">WORKSPACE <span>v1.15</span></div><nav aria-label="Main navigation">${navItems.map(([id,ic,label])=>`<a href="#${id}" data-nav="${id}">${icon(ic)}<span>${label}</span>${id==='midnight'?'<span class="nav-mark">NEW</span>':''}</a>`).join('')}</nav><div class="sidebar-notice">${icon('layers')}<span>Built around CIP-113<small>Standard status: Proposed</small></span></div><div class="sidebar-bottom"><div class="open-source"><span class="mini-label">MADE FOR CARDANO</span><h3>Build something<br>that matters.</h3><p>Open source. Community first.</p>${external(CONFIG.github,`${icon('github')} Explore the code`,'btn secondary compact')}</div><button class="support-link" data-action="donate">${icon('heart')} Support this project</button><a class="creator" href="https://x.com/${CONFIG.x}" target="_blank" rel="noopener noreferrer"><span class="avatar">K</span><span>Built by KShot<small>@${CONFIG.x}</small></span>${icon('x')}</a></div></aside><div class="mobile-shade" data-action="menu"></div><div class="app-body"><header class="topbar"><div class="breadcrumbs"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><span class="desktop-only">Workspace</span><span class="slash desktop-only">/</span><strong id="breadcrumb">Token studio</strong></div><div class="topbar-actions"><label class="network-select">${icon('globe')}<span class="sr-only">Cardano network</span><select id="network-select" aria-label="Cardano network">${Object.entries(NETWORKS).map(([key,n])=>`<option value="${key}" ${key===state.network?'selected':''}>${n.name}${key!=='mainnet'?' testnet':''}</option>`).join('')}</select></label><button class="btn primary wallet-button" data-action="wallet" id="wallet-button">${icon('wallet')}<span>Connect wallet</span></button></div></header><main id="main" tabindex="-1"></main><footer class="footer"><span>PRISM is an independent, open-source project by <a href="https://x.com/${CONFIG.x}" target="_blank" rel="noopener noreferrer">@${CONFIG.x}</a>.</span><span>Cardano × RealFi × Midnight <span class="footer-separator">/</span> <button data-action="share">Share the project ${icon('share')}</button></span></footer></div><input id="import-file" type="file" accept="application/json,.json" hidden>`;
}
function header(eyebrow,title,description,action=''){return `<section class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</section>`;}
function render(){
  const route=location.hash.slice(1)||'studio';state.route=navItems.some(n=>n[0]===route)?route:'studio';
  $$('[data-nav]').forEach(el=>{const active=el.dataset.nav===state.route;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  $('#breadcrumb').textContent=navItems.find(n=>n[0]===state.route)[2];
  document.title=`PRISM · ${navItems.find(n=>n[0]===state.route)[2]}`;
  document.body.classList.remove('menu-open');$('.mobile-menu').setAttribute('aria-expanded','false');updateNavAccess();
  const pages={studio:studio,learn:learn,realfi:realfi,midnight:midnight,network:network,guide:guide};
  $('#main').innerHTML=pages[state.route]();
  if(state.route==='studio'){renderPreview();updateSave();}
  if(state.route==='realfi')updateCredit();
  if(state.route==='network')renderNetworkData();
}

function studio(){return `${header('THE PROGRAMMABLE TOKEN STUDIO','Your asset. <span class="accent-text">Your rules.</span>','Turn a token idea into a testable design. Built around Cardano’s CIP-113.',`<button class="btn secondary" data-action="import">${icon('upload')} Import design</button>`)}<div class="ecosystem-strip"><span>${icon('layers')} Native Cardano assets</span><span class="strip-divider"></span><a href="#realfi">${icon('chart')} Real-world possibilities</a><span class="strip-divider"></span><a href="#midnight">${icon('moon')} Privacy with Midnight</a><span class="strip-end">DESIGN WORKSPACE ${icon('sliders')}</span></div><div class="section-heading"><h2>Start with a possibility</h2><span>Choose a template to shape your rules</span></div><div class="template-grid">${TEMPLATES.map(t=>`<button class="template ${state.design.template===t.id?'selected':''}" data-template="${t.id}" aria-pressed="${state.design.template===t.id}"><span class="template-icon ${t.accent}">${icon(t.icon)}</span><span><strong>${t.name}</strong><small>${t.description}</small></span><span class="selection-dot">${state.design.template===t.id?icon('check'):''}</span></button>`).join('')}</div><div class="studio-layout"><section class="panel editor-panel"><div class="editor-tabs" role="tablist" aria-label="Studio steps">${[['design','01','Design'],['test','02','Test transfer'],['export','03','Export']].map(([key,num,label])=>`<button role="tab" id="tab-${key}" aria-controls="editor-content" aria-selected="${state.tab===key}" tabindex="${state.tab===key?0:-1}" data-tab="${key}" class="${state.tab===key?'active':''}"><span>${num}</span>${label}</button>`).join('')}</div><div id="editor-content" role="tabpanel" aria-labelledby="tab-${state.tab}">${editorContent()}</div><div class="editor-footer"><span>${icon('lock')}<span id="save-status">Draft saved on this device</span></span><button class="text-button" data-action="reset">Reset design</button></div></section><aside class="preview-column" aria-label="Design preview"><div id="design-preview"></div><section class="panel architecture"><div class="section-heading"><h2>How the rules connect</h2>${pill('CIP-113')}</div><div class="architecture-row"><div>${icon('wallet')}<span>Smart wallet</span></div><span class="connector"></span><div>${icon('layers')}<span>Dispatcher</span></div><span class="connector"></span><div>${icon('shield')}<span>Rule delegate</span></div></div><p>A transfer invokes the shared framework and token-specific logic. Your issuer defines the rules.</p><a href="#guide" class="text-link">Explore the architecture ${icon('book')}</a></section><div class="quiet-note">${icon('info')}<span>This is a design workspace. It does not issue tokens or submit transactions.</span></div></aside></div>`;}
function editorContent(){
  const d=state.design;
  if(state.tab==='test')return `<div class="editor-body"><div class="panel-title"><div><h2>Put your rules to the test</h2><p>Try a transfer between fictional participants.</p></div>${pill('LOCAL SIMULATION','amber')}</div><div class="form-grid">${field('Transfer amount',`<div class="input-suffix"><input id="test-amount" inputmode="decimal" value="${esc(state.scenario.amount)}" autocomplete="off"><span>${esc(d.ticker)}</span></div>`)}${field('Test recipient',`<select id="test-recipient">${Object.entries(PARTICIPANTS).map(([k,v])=>`<option value="${k}" ${state.scenario.recipient===k?'selected':''}>${v.name}</option>`).join('')}</select>`)}</div>${d.pausable?`<label class="check-label pause-control"><input type="checkbox" id="test-paused" ${d.paused?'checked':''}> Simulate an issuer pause</label>`:''}<button class="btn primary full" data-action="simulate">${icon('play')} Run transfer simulation</button><div id="simulation-result" aria-live="polite">${simulationResult()}</div><p class="fine-print">Checks model your settings. They do not execute a validator, check an on-chain balance, verify identity, or produce a transaction.</p>${sequenceLab()}${substandardLab()}</div>`;
  if(state.tab==='export')return `<div class="editor-body"><div class="panel-title"><div><h2>Take your idea further</h2><p>A portable design for you and your contributors.</p></div>${icon('code')}</div><div class="notice">${icon('info')}<span>This JSON is a PRISM design manifest. A developer must implement and review the token’s validators before deployment.</span></div><div class="code-header"><span>prism-design.json</span><button class="icon-btn" data-action="copy-manifest" aria-label="Copy design JSON">${icon('copy')}</button></div><pre class="code-preview" id="manifest-code">${esc(manifestText())}</pre><div class="button-row"><button class="btn primary" data-action="export">${icon('download')} Download design</button><a class="btn secondary" href="#guide">${icon('book')} Build guide</a></div><p class="fine-print">Imports are verified before they open: amounts must be exact decimal strings (a JSON number is rejected, never rounded), the token summary must match the design, and a file claiming deployment, a verified proof, or an affiliation is rejected.</p><div class="section-divider"></div><div class="panel-title"><div><h2>Registry entry preview</h2><p>The design information a CIP-113 registry entry would need to describe — shown before any code exists.</p></div>${pill('NOT A CIP DATUM','amber')}</div><div class="notice">${icon('info')}<span><strong>Application-specific preview, not a CIP datum.</strong> A real registry entry is an on-chain linked-list node created by the pinned reference implementation, carrying a deployed token policy ID and a Plutus Data encoding. This preview has neither — it lists what your design contributes and what a deployment still has to supply. PRISM does not register anything.</span></div><div class="code-header"><span>prism-registry-preview.json</span><button class="icon-btn" data-action="copy-registry-preview" aria-label="Copy registry preview JSON">${icon('copy')}</button></div><pre class="code-preview" id="registry-preview-code">${esc(registryPreviewText())}</pre><div class="button-row"><button class="btn secondary" data-action="export-registry-preview">${icon('download')} Download preview</button></div><p class="fine-print">Amounts are exact base units (BigInt). The preview is deterministic — exporting the same design twice gives the same file, so reviewers can diff it.</p></div>`;
  return `<div class="editor-body"><div class="panel-title"><div><h2>Token identity</h2><p>Every asset starts with a name.</p></div><span class="step-label">01 / 03</span></div><div class="form-grid"><div class="span-two">${field('Asset name',`<input data-design="tokenName" value="${esc(d.tokenName)}" maxlength="64" autocomplete="off" placeholder="Give your asset a name">`,'Maximum 32 UTF-8 bytes.')}</div>${field('Ticker',`<input data-design="ticker" value="${esc(d.ticker)}" maxlength="8" autocomplete="off" spellcheck="false">`)}${field('Decimals',`<select data-design="decimals">${[0,1,2,3,4,5,6].map(n=>`<option ${d.decimals===n?'selected':''} value="${n}">${n}${n===0?' · whole tokens':''}</option>`).join('')}</select>`)}${field('Designed supply',`<input data-design="supply" value="${esc(d.supply)}" inputmode="decimal" autocomplete="off">`)}${field('Transfer limit',`<div class="input-suffix"><input data-design="limit" value="${esc(d.limit)}" inputmode="decimal" autocomplete="off"><span id="limit-ticker">${esc(d.ticker)}</span></div>`)}</div><div id="design-errors" class="validation" role="status"></div><div class="section-divider"></div><div class="panel-title rules-title"><div><h2>Make the rules</h2><p>Choose what a transfer needs to satisfy.</p></div><span id="rule-count" class="count-badge">4 active</span></div><div class="rule-list">${toggle('allowlist','Approved participants','Only modeled allowlist members can receive.','users')}${toggle('limitEnabled','Transfer limits','Set the maximum amount per transfer.','sliders')}${toggle('pausable','Issuer controls','Model transfer pauses and frozen participants.','shield')}${toggle('identity','Private eligibility','Plan eligibility checks with a Midnight attestation.','fingerprint')}</div><div class="section-divider"></div><div class="panel-title rules-title"><div><h2>CIP-113 substandard module</h2><p>The reference rule set a transfer hook would implement.</p></div>${pill('LOCAL MODEL','amber')}</div>${field('Reference module',`<select data-design="substandard" aria-label="CIP-113 substandard module">${SUBSTANDARDS.map(s=>`<option value="${s.id}" ${d.substandard===s.id?'selected':''}>${s.name}</option>`).join('')}</select>`)}<div id="substandard-summary">${substandardSummary()}</div><div class="section-divider"></div><div class="panel-title rules-title"><div><h2>Design review</h2><p>What this design's own settings imply \u2014 before you test or export it.</p></div>${pill('LOCAL REVIEW','amber')}</div><div id="design-review">${designReview()}</div><button class="btn primary full next-step" data-tab="test">${icon('play')} Test this design</button></div>`;
}
function manifestText(){try{return JSON.stringify(makeManifest(state.design,state.network),null,2);}catch(e){return `Fix the design before exporting:\n${e.message}`;}}
function registryPreviewText(){try{return JSON.stringify(registryDatumPreview(state.design,state.network),null,2);}catch(e){return `Fix the design before previewing:\n${e.message}`;}}
function renderPreview(){
  if(!$('#design-preview'))return;
  const d=state.design,t=TEMPLATES.find(t=>t.id===d.template),count=['allowlist','limitEnabled','pausable','identity'].filter(k=>d[k]).length;
  $('#design-preview').innerHTML=`<div class="preview-heading"><span>YOUR ASSET, AT A GLANCE</span>${pill('DESIGN · NOT ISSUED')}</div><div class="asset-card ${t.accent}"><div class="asset-card-top"><span class="asset-symbol">${icon(t.icon)}</span><span class="asset-standard">CARDANO<br><b>CIP–113</b></span></div><div class="asset-card-title"><span class="asset-ticker">${esc(d.ticker)||'TOKEN'}</span><h2>${esc(d.tokenName)||'Your new asset'}</h2><span>Programmable token design</span></div><div class="asset-card-bottom"><div><span>DESIGNED SUPPLY</span><strong>${Number.isFinite(Number(d.supply))?fmt(Number(d.supply)):'—'}</strong></div><div><span>NETWORK</span><strong>${NETWORKS[state.network].name}</strong></div></div></div><div class="panel preview-details"><div><span>Asset type</span><strong>${t.name}</strong></div><div><span>Precision</span><strong>${d.decimals} decimals</strong></div><div><span>Transfer policy</span><strong>${d.allowlist?'Permissioned':'Open access'}</strong></div><div><span>Substandard</span><strong>${esc(substandardById(d.substandard)?.short??'Generic rules')}</strong></div><div><span>Active rules</span><strong class="accent-text">${count} configured</strong></div><div><span>Privacy plan</span><strong>${d.identity?`${icon('moon')} Midnight`:'None selected'}</strong></div></div>`;
  const errors=validateDesign(d);if($('#design-errors'))$('#design-errors').textContent=errors.join(' ');
  if($('#substandard-summary'))$('#substandard-summary').innerHTML=substandardSummary();
  if($('#design-review'))$('#design-review').innerHTML=designReview();
  if($('#rule-count'))$('#rule-count').textContent=`${count} active`;
  if($('#limit-ticker'))$('#limit-ticker').textContent=d.ticker;
  updateSave();
}
function simulationResult(){
  const r=state.simulation;
  if(!r)return `<div class="simulation-empty">${icon('play')}<strong>What happens when this token moves?</strong><span>Run a scenario to see each rule evaluated.</span></div>`;
  return `<div class="simulation-result ${r.allowed?'passed':'failed'}"><div class="result-heading"><span class="result-icon">${icon(r.allowed?'check':'close')}</span><div><h3>${r.allowed?'Transfer allowed by model':'Transfer blocked by model'}</h3><p>${r.checks.filter(c=>c.pass).length} of ${r.checks.length} checks passed · no transaction sent</p></div></div><div class="check-results">${r.checks.map(c=>`<div class="check-result ${c.pass?'pass':'fail'}">${icon(c.pass?'check':'close')}<span><strong>${c.name}</strong><small>${esc(c.detail)}</small></span></div>`).join('')}</div></div>`;
}

function sequencePresets(d){
  const cap=d.limitEnabled?d.limit:'250';
  return [
    {id:'distribution',label:'Distribution & onward moves',steps:[{from:'issuer',to:'approved',amount:'250'},{from:'approved',to:'pending',amount:'100'},{from:'approved',to:'blocked',amount:'50'},{from:'issuer',to:'approved',amount:'100'}]},
    {id:'fund-spend',label:'Fund, spend back, overspend',steps:[{from:'issuer',to:'approved',amount:'200'},{from:'approved',to:'issuer',amount:'150'},{from:'approved',to:'issuer',amount:'100'}]},
    {id:'cap-pair',label:'Two transfers at the cap',steps:[{from:'issuer',to:'approved',amount:cap},{from:'issuer',to:'approved',amount:cap}]},
  ];
}
function currentSeqPreset(){const list=sequencePresets(state.design);return list.find(p=>p.id===state.seqPreset)??list[0];}
function customSteps(){if(!state.seqCustom)state.seqCustom=copySequenceSteps(currentSeqPreset().steps);return state.seqCustom;}
function seqSteps(){return state.seqMode==='custom'?customSteps():currentSeqPreset().steps;}
function sequenceLab(){
  const d=state.design,custom=state.seqMode==='custom',steps=seqSteps();
  const accountOptions=sel=>Object.entries(LEDGER_ACCOUNTS).map(([k,v])=>`<option value="${k}" ${k===sel?'selected':''}>${v.name}</option>`).join('');
  const list=custom
    ?`<div class="seq-editor">${steps.map((s,i)=>`<div class="seq-edit-row"><span class="seq-num">${i+1}</span><label class="sr-only" for="seq-from-${i}">Step ${i+1} sender</label><select id="seq-from-${i}" class="seq-from" data-seq-field="from" data-seq-index="${i}">${accountOptions(s.from)}</select><span class="seq-arrow" aria-hidden="true">→</span><label class="sr-only" for="seq-to-${i}">Step ${i+1} recipient</label><select id="seq-to-${i}" class="seq-to" data-seq-field="to" data-seq-index="${i}">${accountOptions(s.to)}</select><label class="sr-only" for="seq-amount-${i}">Step ${i+1} amount in ${esc(d.ticker)}</label><span class="seq-amount"><input id="seq-amount-${i}" data-seq-field="amount" data-seq-index="${i}" inputmode="decimal" autocomplete="off" value="${esc(s.amount)}"><span>${esc(d.ticker)}</span></span><span class="seq-row-actions"><button class="icon-btn" data-seq-move="-1" data-seq-index="${i}" ${i===0?'disabled':''} aria-label="Move step ${i+1} up">${icon('chevron','seq-up')}</button><button class="icon-btn" data-seq-move="1" data-seq-index="${i}" ${i===steps.length-1?'disabled':''} aria-label="Move step ${i+1} down">${icon('chevron','seq-down')}</button><button class="icon-btn" data-seq-remove="${i}" ${steps.length<=1?'disabled':''} aria-label="Remove step ${i+1}">${icon('close')}</button></span></div>`).join('')}</div><button class="btn secondary full seq-add" data-action="seq-add" ${steps.length>=12?'disabled':''}>${icon('plus')} Add a transfer step</button>`
    :`<ol class="seq-steps">${steps.map((s,i)=>`<li><span class="seq-num">${i+1}</span><span>${esc(LEDGER_ACCOUNTS[s.from]?.name??s.from)} → ${esc(LEDGER_ACCOUNTS[s.to]?.name??s.to)}</span><strong>${esc(s.amount)} ${esc(d.ticker)}</strong></li>`).join('')}</ol>`;
  return `<div class="section-divider"></div><div class="panel-title"><div><h2>Sequence lab · transfers in order</h2><p>One transfer changes the balances the next one is checked against. The issuer starts holding the full designed supply; every other modeled account starts at zero.</p></div>${pill('LOCAL SIMULATION','amber')}</div><div class="preset-chips" role="group" aria-label="Transfer sequence scenarios">${sequencePresets(d).map(p=>`<button class="chip ${!custom&&state.seqPreset===p.id?'selected':''}" data-seq-preset="${p.id}" aria-pressed="${!custom&&state.seqPreset===p.id}">${p.label}</button>`).join('')}<button class="chip ${custom?'selected':''}" data-action="seq-customize" aria-pressed="${custom}">${custom?'Your own sequence':'Build your own'}</button></div>${custom?`<p class="fine-print seq-custom-note">Start from the preset you were viewing, then change senders, recipients, and amounts, add steps (up to 12), reorder them, or remove them. Editing clears the last run — run it again to see the new order evaluated.</p>`:''}${list}<button class="btn primary full" data-action="seq-simulate">${icon('play')} Run sequence</button><div id="seq-result" aria-live="polite">${seqResultView()}</div><p class="fine-print">A modeled ledger only: balances are fictional, no wallet or on-chain balance is read, and a blocked step leaves every balance unchanged — later steps are still evaluated against the ledger as it stands, so you can see the knock-on effect of a denial.</p>`;
}
function seqResultView(){
  const r=state.seqResult,d=state.design;
  if(!r)return `<div class="simulation-empty">${icon('layers')}<strong>What happens across several transfers?</strong><span>Run a sequence to watch balances and rules interact, step by step.</span></div>`;
  if(r.invalid)return `<div class="validation" role="alert">Fix the design before running a sequence: ${esc((r.errors??[]).join(' '))}</div>`;
  return `<div class="simulation-result ${r.appliedCount===r.steps.length?'passed':'failed'}"><div class="result-heading"><span class="result-icon">${icon(r.appliedCount===r.steps.length?'check':'close')}</span><div><h3>${r.appliedCount} of ${r.steps.length} transfers applied in the model</h3><p>${esc(formatUnits(BigInt(r.transferredBaseUnits),d.decimals))} ${esc(d.ticker)} moved in total · no transaction sent</p></div></div><div class="seq-balances"><h4>FINAL MODELED BALANCES</h4><dl>${Object.entries(r.balances).map(([k,v])=>`<div><dt>${esc(LEDGER_ACCOUNTS[k]?.name??k)}</dt><dd>${esc(formatUnits(BigInt(v),d.decimals))} ${esc(d.ticker)}</dd></div>`).join('')}</dl></div>${r.steps.map((s,i)=>`<div class="seq-step ${s.allowed?'pass':'fail'}"><div class="seq-step-head">${icon(s.allowed?'check':'close')}<strong>Step ${i+1} · ${esc(LEDGER_ACCOUNTS[s.from]?.name??s.from)} → ${esc(LEDGER_ACCOUNTS[s.to]?.name??s.to)} · ${esc(s.amount)} ${esc(d.ticker)}</strong><span>${s.allowed?'Applied':'Blocked · balances unchanged'}</span></div><div class="check-results">${s.checks.map(c=>`<div class="check-result ${c.pass?'pass':'fail'}">${icon(c.pass?'check':'close')}<span><strong>${c.name}</strong><small>${esc(c.detail)}</small></span></div>`).join('')}</div></div>`).join('')}</div>`;
}

const KYC_OK={certPresent:true,certTrustedIssuer:true,certSignatureValid:true,certNamesSender:true,certExpired:false,paused:false};
const SUB_PRESETS={
  'freeze-seize':[
    {id:'clean',label:'Clean transfer',scenario:{senderDenylisted:false,recipientDenylisted:false}},
    {id:'sender-denied',label:'Sender denylisted',scenario:{senderDenylisted:true,recipientDenylisted:false}},
    {id:'recipient-denied',label:'Recipient denylisted',scenario:{senderDenylisted:false,recipientDenylisted:true}},
    {id:'both-denied',label:'Both denylisted',scenario:{senderDenylisted:true,recipientDenylisted:true}},
  ],
  kyc:[
    {id:'valid',label:'Valid certificate',scenario:{...KYC_OK}},
    {id:'missing',label:'No certificate',scenario:{certPresent:false,certTrustedIssuer:false,certSignatureValid:false,certNamesSender:false,certExpired:false,paused:false}},
    {id:'untrusted',label:'Untrusted issuer',scenario:{...KYC_OK,certTrustedIssuer:false}},
    {id:'bad-signature',label:'Invalid signature',scenario:{...KYC_OK,certSignatureValid:false}},
    {id:'wrong-sender',label:'Certificate names another sender',scenario:{...KYC_OK,certNamesSender:false}},
    {id:'expired',label:'Expired certificate',scenario:{...KYC_OK,certExpired:true}},
    {id:'paused',label:'Issuer paused',scenario:{...KYC_OK,paused:true}},
  ],
  'kyc-extended':[
    {id:'valid',label:'Fully verified transfer',scenario:{...KYC_OK,recipientAllowlisted:true,recipientEntryExpired:false,selfTransfer:false}},
    {id:'recipient-unlisted',label:'Recipient not allowlisted',scenario:{...KYC_OK,recipientAllowlisted:false,recipientEntryExpired:false,selfTransfer:false}},
    {id:'recipient-expired',label:'Recipient entry expired',scenario:{...KYC_OK,recipientAllowlisted:true,recipientEntryExpired:true,selfTransfer:false}},
    {id:'sender-expired',label:'Sender certificate expired',scenario:{...KYC_OK,certExpired:true,recipientAllowlisted:true,recipientEntryExpired:false,selfTransfer:false}},
    {id:'self',label:'Self-transfer (unlisted)',scenario:{...KYC_OK,recipientAllowlisted:false,recipientEntryExpired:false,selfTransfer:true}},
  ],
};
const SEIZURE_PRESETS=[
  {id:'lawful',label:'Authorised · holder denylisted',scenario:{actorAuthorised:true,holderDenylisted:true}},
  {id:'clean-holder',label:'Authorised · holder clean',scenario:{actorAuthorised:true,holderDenylisted:false}},
  {id:'stranger',label:'Unauthorised · holder denylisted',scenario:{actorAuthorised:false,holderDenylisted:true}},
];
function currentSubPreset(){const list=SUB_PRESETS[state.design.substandard]??[];return list.find(p=>p.id===state.subPreset)??list[0];}
function designReview(){const a=auditDesign(state.design);const icons={blocker:'close',warning:'info',note:'info',ok:'check'};const summary=a.invalid?`${a.counts.blocker} blocker \u2014 fix the design before anything else`:[a.counts.warning?`${a.counts.warning} warning${a.counts.warning>1?'s':''} to consider`:'No warnings',a.counts.note?`${a.counts.note} note${a.counts.note>1?'s':''}`:'',`${a.counts.ok} ok`].filter(Boolean).join(' \u00b7 ');return `<div class="check-results review-results">${a.findings.map(f=>`<div class="check-result ${f.level==='ok'?'pass':f.level}">${icon(icons[f.level])}<span><strong>${esc(f.title)}</strong><small>${esc(f.detail)}</small></span></div>`).join('')}</div><p class="fine-print">Design review summary: ${summary}. A local review of this design's own settings \u2014 not a security audit, not validator review, and no guarantee a design is safe or deployable. A developer must still implement and independently review the token's validators.</p>`;}
function substandardSummary(){const s=substandardById(state.design.substandard)??SUBSTANDARDS[0];return `<div class="notice substandard-note">${icon('layers')}<span><strong>${esc(s.name)}.</strong> ${esc(s.summary)} ${s.source?external(s.source,'Foundation module reference','text-link'):''}<br><span class="fine-print">Modeled locally in the Test step. PRISM does not deploy this module or check any on-chain list, certificate, or allowlist.</span></span></div>`;}
function checkList(r,allowedText,blockedText){return `<div class="simulation-result ${r.allowed?'passed':'failed'}"><div class="result-heading"><span class="result-icon">${icon(r.allowed?'check':'close')}</span><div><h3>${r.allowed?allowedText:blockedText}</h3><p>${r.checks.filter(c=>c.pass).length} of ${r.checks.length} checks passed · local model only</p></div></div><div class="check-results">${r.checks.map(c=>`<div class="check-result ${c.pass?'pass':'fail'}">${icon(c.pass?'check':'close')}<span><strong>${c.name}</strong><small>${esc(c.detail)}</small></span></div>`).join('')}</div></div>`;}
function substandardLab(){
  const s=substandardById(state.design.substandard);
  if(!s||s.id==='generic')return '';
  const preset=currentSubPreset();
  return `<div class="section-divider"></div><div class="panel-title"><div><h2>Substandard lab · ${esc(s.name)}</h2><p>Denial paths from the Foundation reference module, modeled check by check.</p></div>${pill('LOCAL SIMULATION','amber')}</div><div class="preset-chips" role="group" aria-label="Substandard scenarios">${(SUB_PRESETS[s.id]??[]).map(p=>`<button class="chip ${preset?.id===p.id?'selected':''}" data-sub-preset="${p.id}" aria-pressed="${preset?.id===p.id}">${p.label}</button>`).join('')}</div><button class="btn primary full" data-action="sub-simulate">${icon('play')} Run ${esc(s.short)} checks</button><div id="sub-result" aria-live="polite">${subResult()}</div>${s.id==='freeze-seize'?seizureLab():''}<p class="fine-print">Faithful to the reference module’s documented checks. No on-chain denylist, certificate, or allowlist is read; nothing is frozen, seized, or verified here.</p>`;
}
function subResult(){const r=state.subResult;if(!r)return `<div class="simulation-empty">${icon('shield')}<strong>Pick a scenario and run it.</strong><span>Each check mirrors the reference validator’s documented decision.</span></div>`;return checkList(r,'Transfer allowed by module model','Transfer blocked by module model');}
function seizureLab(){const preset=SEIZURE_PRESETS.find(p=>p.id===state.seizurePreset)??SEIZURE_PRESETS[0];return `<div class="section-divider"></div><div class="panel-title"><div><h2>Issuer action · freeze &amp; seize</h2><p>A third-party action on a holder, separate from transfers.</p></div>${pill('LOCAL SIMULATION','amber')}</div><div class="preset-chips" role="group" aria-label="Seizure scenarios">${SEIZURE_PRESETS.map(p=>`<button class="chip ${preset.id===p.id?'selected':''}" data-seizure-preset="${p.id}" aria-pressed="${preset.id===p.id}">${p.label}</button>`).join('')}</div><button class="btn secondary full" data-action="seizure-simulate">${icon('shield')} Model seizure</button><div id="seizure-result" aria-live="polite">${seizureResult()}</div>`;}
function seizureResult(){const r=state.seizureResult;if(!r)return `<div class="simulation-empty">${icon('shield')}<strong>Who may seize, and from whom?</strong><span>Run a scenario to see the authority and denylist checks.</span></div>`;return checkList(r,'Seizure permitted by model','Seizure blocked by model');}

function realfi(){return `${header('REAL ASSETS. MEANINGFUL UTILITY.','Finance beyond the screen.','Explore how programmable ownership can support real-world financial agreements.',external(CONFIG.realfiApp,'Open RealFi','btn secondary'))}<section class="realfi-banner"><div><span class="eyebrow">REALFI ECOSYSTEM</span><h2>Real-world value.<br>On-chain possibilities.</h2><p>RealFi’s official site lists USDrf and sUSDrf as live on Cardano. Explore the product at its source, then model your own asset rules here.</p><span class="source-caption">Source: realfi.co · checked ${CONFIG.verified}</span></div><div class="realfi-flow"><div>${icon('building')}<span>Real-world assets</span></div><span class="vertical-link"></span><div class="flow-token"><span>USDrf</span><small>RealFi stablecoin</small></div><span class="vertical-link"></span><div>${icon('layers')}<span>Cardano</span></div></div></section><div class="two-column"><section class="panel"><div class="panel-heading"><div><h2>Private credit scenario</h2><p>Explore a hypothetical, simple-interest agreement.</p></div>${pill('MODEL','amber')}</div><div class="panel-content"><div class="form-grid">${field('Principal (USD)',`<input type="number" data-credit="principal" min="1" max="1000000000000" value="${state.credit.principal}">`)}${field('Annual interest rate (%)',`<input type="number" data-credit="rate" min="0" max="100" step="0.1" value="${state.credit.rate}">`)}${field('Term (months)',`<input type="number" data-credit="months" min="1" max="360" value="${state.credit.months}">`)}${field('Collateral value (USD)',`<input type="number" data-credit="collateral" min="1" max="1000000000000" value="${state.credit.collateral}">`)}<div class="span-two">${field('Maximum advance rate (%)',`<div class="range-field"><input type="range" min="1" max="100" data-credit="advance" value="${state.credit.advance}"><output id="advance-output">${state.credit.advance}%</output></div>`)}</div></div><div id="credit-errors" class="validation" role="status"></div><div class="notice">${icon('info')}<span>Illustrative inputs, not RealFi rates, a loan offer, or a forecast. No fees, defaults, price changes, or compounding are included.</span></div><button class="btn primary full" data-action="credit-template">${icon('sliders')} Design a private credit token</button></div></section><section class="panel scenario-panel"><div class="panel-heading"><h2>The numbers behind the rules</h2>${icon('chart')}</div><div class="panel-content" id="credit-output"></div></section></div><section class="panel amort-panel"><div class="panel-heading"><div><h2>Amortized repayment schedule</h2><p>The same scenario repaid in equal monthly payments — the structure most term loans use. Interest is charged each month on the remaining balance, so it costs less than simple interest on the full principal.</p></div>${pill('MODEL','amber')}</div><div class="panel-content" id="amort-output"></div></section><section class="panel connection-panel"><div>${icon('layers')}<h2>Where CIP-113 fits</h2><p>Ownership can be restricted to eligible participants; transfers can be paused according to issuer rules. These controls are building blocks. They do not prove asset backing, legal rights, or compliance.</p></div><div>${icon('moon')}<h2>Where Midnight fits</h2><p>A privacy design could establish eligibility while keeping the supporting evidence private. Connecting that result to Cardano requires an attestation or bridge that you explicitly trust.</p><a href="#midnight" class="text-link">Explore privacy requirements ${icon('fingerprint')}</a></div></section><p class="fine-print">PRISM is independent of RealFi. It does not mint, redeem, stake, or sell USDrf or sUSDrf. Product interactions take place in RealFi’s official app.</p>`;}
function updateCredit(){try{const r=creditScenario(state.credit);$('#advance-output').textContent=`${state.credit.advance}%`;$('#credit-errors').textContent='';$('#credit-output').innerHTML=`<div class="metric-large"><span>Modeled repayment</span><strong>${money(r.total)}</strong><small>Principal + simple interest</small></div><div class="metric-pair"><div><span>Interest over term</span><strong>${money(r.interest)}</strong></div><div><span>Loan-to-value</span><strong>${fmt(r.ltv)}%</strong></div></div><div class="meter-label"><span>Collateral advance capacity</span><strong>${money(r.ceiling)}</strong></div><div class="meter"><span style="width:${Math.min(100,r.ceiling?state.credit.principal/r.ceiling*100:100)}%" class="${r.withinLimit?'':'over'}"></span></div><div class="status-box ${r.withinLimit?'good':'bad'}">${icon(r.withinLimit?'check':'close')}<span><strong>${r.withinLimit?'Within modeled limit':'Above modeled limit'}</strong><small>${money(Math.abs(r.headroom))} ${r.withinLimit?'headroom remaining':'above your advance ceiling'}</small></span></div><p class="fine-print">Calculation: principal × annual rate × months ÷ 12. This model does not evaluate creditworthiness or enforce an agreement.</p>`;renderAmort(r.interest);}catch(e){$('#credit-errors').textContent=e.message;$('#credit-output').innerHTML='<div class="empty-state">Check your scenario inputs to calculate a result.</div>';renderAmort(null);}}
function renderAmort(simpleInterest){const el=$('#amort-output');if(!el)return;try{const a=amortizationSchedule(state.credit);const full=a.schedule.length<=24,shown=full?a.schedule:a.schedule.filter(row=>row.month<=6||row.month%12===0||row.month===a.schedule.length);const saved=simpleInterest===null?null:simpleInterest-a.totalInterest;el.innerHTML=`<div class="metric-pair amort-metrics"><div><span>Monthly payment</span><strong>${money2(a.monthlyPayment)}</strong></div><div><span>Total interest (amortized)</span><strong>${money2(a.totalInterest)}</strong></div><div><span>Total repaid</span><strong>${money2(a.total)}</strong></div></div>${saved===null?'':saved>0.005?`<div class="status-box good">${icon('check')}<span><strong>${money2(saved)} less interest than the simple-interest model</strong><small>Each payment reduces the balance the next month's interest is charged on.</small></span></div>`:`<div class="status-box good">${icon('check')}<span><strong>Same interest as the simple-interest model</strong><small>At a 0% rate there is no interest under either structure.</small></span></div>`}<div class="table-scroll"><table class="amort-table"><caption class="sr-only">Modeled monthly repayment schedule</caption><thead><tr><th scope="col">Month</th><th scope="col">Payment</th><th scope="col">Interest</th><th scope="col">Principal</th><th scope="col">Balance left</th></tr></thead><tbody>${shown.map(row=>`<tr><td>${row.month}</td><td>${money2(row.payment)}</td><td>${money2(row.interest)}</td><td>${money2(row.principal)}</td><td>${money2(row.balance)}</td></tr>`).join('')}</tbody></table></div><p class="fine-print">${full?`All ${a.schedule.length} modeled payments.`:`Showing the first 6 months, each 12-month mark, and the final month of ${a.schedule.length}.`} The final payment is adjusted so the balance ends at exactly $0.00. Illustrative only — no fees, taxes, insurance, defaults, prepayment, or rate changes, and not a loan offer or any product's terms.</p>`;}catch(e){el.innerHTML=`<div class="empty-state">The schedule needs a whole number of months between 1 and 360. The simple-interest model above still uses the term you entered.</div>`;}}

function midnight(){const e=state.eligibility;return `${header('MIDNIGHT PRIVACY WORKSPACE','Prove enough. <span class="purple-text">Reveal less.</span>','Explore an eligibility design with a clear boundary between private evidence and public decisions.',`<button class="btn purple" data-action="midnight-wallet">${icon('moon')} ${state.midnight?'Wallet connected':'Connect Midnight'}</button>`)}<div class="privacy-banner"><span class="large-icon">${icon('fingerprint')}</span><div><h2>Private evidence. Public eligibility.</h2><p>Midnight provides tools for zero-knowledge applications. PRISM connects to its wallet API and helps you plan an eligibility flow.</p></div>${pill('CONNECTOR V4','purple')}</div><div class="two-column privacy-layout"><section class="panel"><div class="panel-heading"><div><h2>Eligibility sandbox</h2><p>Fictional inputs, evaluated in this browser.</p></div>${icon('lock')}</div><div class="panel-content"><div class="privacy-label">PRIVATE TEST INPUTS <span>Not saved or transmitted</span></div><div class="form-grid">${field('Example eligibility score',`<input data-eligibility="score" type="number" min="0" max="100" value="${e.score}">`)}${field('Example age',`<input data-eligibility="age" type="number" min="0" max="120" value="${e.age}">`)}</div><label class="check-label"><input type="checkbox" data-eligibility="approved" ${e.approved?'checked':''}> Example participant is in an approved region</label><div class="section-divider"></div><div class="privacy-label">PUBLIC POLICY</div>${field('Minimum eligibility score',`<input data-eligibility="minimum" type="number" min="0" max="100" value="${e.minimum}">`)}<label class="check-label"><input type="checkbox" data-eligibility="adult" ${e.adult?'checked':''}> Require age 18 or above</label><label class="check-label"><input type="checkbox" data-eligibility="region" ${e.region?'checked':''}> Require an approved region</label><button class="btn purple full" data-action="eligibility">${icon('play')} Evaluate locally</button><p class="fine-print">Use fictional data only. This evaluation is ordinary JavaScript, not a zero-knowledge proof or a KYC check.</p></div></section><div class="stack"><section class="panel"><div class="panel-heading"><h2>Public result preview</h2>${pill('LOCAL MODEL','amber')}</div><div class="panel-content" id="eligibility-result">${eligibilityResult()}</div></section><section class="panel wallet-status-card"><div class="panel-heading"><h2>Midnight connection</h2>${icon('moon')}</div><div class="panel-content">${state.midnight?`<div class="status-box good">${icon('check')}<span><strong>${esc(state.midnight.name)}</strong><small>${esc(state.midnight.network)} · API ${esc(state.midnight.version)}</small></span></div><code class="break-address">${esc(state.midnight.address)}</code><button class="text-button" data-action="disconnect-midnight">Disconnect from PRISM</button>`:`<p>No wallet connected. An installed Midnight wallet with API v4 can share its public address and connection network.</p><button class="btn secondary full" data-action="midnight-wallet">${icon('wallet')} Choose a Midnight wallet</button>`}</div></section></div></div><section class="panel integration-path"><div class="panel-heading"><h2>From this model to a privacy application</h2>${pill('IMPLEMENTATION REQUIRED')}</div><div class="path-grid"><div><span>01</span><h3>Compact contract</h3><p>Implement a circuit, private witnesses, issuer trust, expiry, and revocation. Review which inputs and outputs are disclosed.</p></div><div><span>02</span><h3>Proof and attestation</h3><p>Deploy the contract, generate real proofs, and define how a signed eligibility result is bound to a holder and a policy.</p></div><div><span>03</span><h3>Cardano enforcement</h3><p>Verify the attestation through a reviewed transfer hook. A Midnight proof alone is not automatically verified by Cardano.</p></div></div><div class="integration-links">${external('https://docs.midnight.network/guides/deploy-and-operate','Midnight contract guide','text-link')}${external(CONFIG.platform+'/tree/main/src/modules/kyc-extended','CIP-113 KYC module','text-link')}</div></section>`;}
function eligibilityResult(){const r=state.eligibilityResult;return r?`<div class="privacy-output ${r.eligible?'eligible':'ineligible'}">${icon(r.eligible?'shield':'lock')}<span>MODELED ELIGIBILITY</span><strong>${r.eligible?'Eligible':'Not eligible'}</strong></div><div class="check-results">${r.checks.map(c=>`<div class="check-result ${c.pass?'pass':'fail'}">${icon(c.pass?'check':'close')}<strong>${c.name}</strong></div>`).join('')}</div><div class="notice">${icon('info')}<span>No proof generated. No attestation issued. No data sent to Midnight or Cardano.</span></div>`:`<div class="simulation-empty">${icon('fingerprint')}<strong>Only the decision belongs here.</strong><span>Run the local model to preview its public output.</span></div>`;}

function network(){return `${header('READ THE NETWORK','A clearer view of Cardano.','Live chain data and a practical smart-wallet tool, with every source in reach.',`<button class="btn secondary" data-action="refresh-network">${icon('refresh')} Refresh data</button>`)}<div id="chain-status" class="source-status" aria-live="polite"></div><div class="network-metrics" id="network-metrics"></div><div class="two-column"><section class="panel"><div class="panel-heading"><div><h2>CIP-113 smart wallet</h2><p>Derive an address from a real owner credential.</p></div>${icon('wallet')}</div><div class="panel-content"><div class="notice">${icon('info')}<span>Address derivation only. Use a reviewed deployment and verify its live parameters before funding. PRISM does not deposit or move funds.</span></div><form id="derive-form">${field('Owner payment address',`<textarea id="owner-address" rows="2" spellcheck="false" required placeholder="${state.network==='mainnet'?'addr1…':'addr_test1…'}">${esc(state.wallet?.address??'')}</textarea>`,'Your original payment credential becomes the smart-wallet owner credential.')}<div class="field-action"><span>Programmable base script hash</span>${state.network==='preview'?'<button type="button" class="text-button" data-action="load-reference">Use Foundation reference</button>':''}</div><label><span class="sr-only">Programmable base script hash</span><input id="base-script" class="mono" maxlength="56" placeholder="28-byte script hash (56 hex characters)" spellcheck="false" required></label><div id="reference-status" class="fine-print"></div><button class="btn primary full" type="submit">${icon('fingerprint')} Derive smart-wallet address</button></form><div id="derived-result" aria-live="polite"></div><p class="fine-print">CIP-30 identifies mainnet versus testnet; it cannot distinguish Preview from Preprod. Ensure your wallet uses the selected testnet.</p></div></section><section class="panel"><div class="panel-heading"><div><h2>Native asset lookup</h2><p>Query actual asset records through Koios.</p></div>${icon('coins')}</div><div class="panel-content"><form id="asset-form">${field('Policy ID',`<input id="asset-policy" class="mono" spellcheck="false" maxlength="56" placeholder="56 hexadecimal characters" required>`)}${field('Asset name (hex)',`<input id="asset-name" class="mono" spellcheck="false" maxlength="64" placeholder="Empty is a valid asset name">`)}<div id="asset-fingerprint" class="fingerprint-preview" aria-live="polite">${fingerprintPreview('','')}</div><button class="btn secondary full" type="submit" id="asset-submit">${icon('globe')} Look up asset</button></form><div id="asset-result" aria-live="polite"></div><p class="fine-print">Native asset existence does not establish CIP-113 registry membership, authenticity, backing, or value.</p></div></section></div><section class="panel inspector-panel"><div class="panel-heading"><div><h2>Address inspector</h2><p>Decode any Shelley address locally — its CIP-19 structure, credential hashes, and whether its shape matches a CIP-113 smart wallet.</p></div>${icon('fingerprint')}</div><div class="panel-content"><form id="inspect-form">${field('Shelley address (addr / addr_test)',`<textarea id="inspect-address" rows="2" spellcheck="false" required placeholder="addr1… or addr_test1…"></textarea>`,'Decoded in this browser only. No lookup is performed: this shows what an address is, never what it holds.')}<button class="btn secondary full" type="submit">${icon('fingerprint')} Inspect address</button></form><div id="inspect-result" aria-live="polite"></div></div></section><section class="panel registry-panel"><div class="panel-heading"><div><h2>Programmable-token registry</h2><p>A registry is specific to its protocol deployment and network.</p></div>${pill(CONFIG.registryApi?'INDEXER CONFIGURED':'INDEXER NOT CONNECTED','amber')}</div><div class="panel-content">${CONFIG.registryApi?`<button class="btn secondary" data-action="registry">Read configured registry</button><div id="registry-results"></div>`:`<div class="registry-empty">${icon('layers')}<div><h3>Bring a verified registry into view.</h3><p>The Foundation’s reference backend exposes deployment and registry endpoints. Configure a hosted indexer to browse them here; PRISM does not invent a global registry or token count.</p>${external(CONFIG.platform,'Reference platform','text-link')}</div></div>`}<div class="section-divider"></div><div class="panel-title"><div><h3>Foundation Preview reference deployment</h3><p>The deployment recorded in the Foundation platform’s pinned Preview configuration — checked live against the chain, not taken on trust.</p></div>${pill('PREVIEW · REFERENCE','amber')}</div><button class="btn secondary" data-action="verify-deployment" ${state.deploymentLoading?'disabled':''}>${icon('shield')} Verify deployment on Preview</button><div id="deployment-results" aria-live="polite">${deploymentResult()}</div><p class="fine-print">This verifies one pinned deployment transaction on the Preview testnet. It does not list or count registry tokens — browsing the registry still requires a Foundation-compatible indexer, which is not connected above. The Foundation reference implementation is research &amp; development — not production-ready, with an independent security audit pending.</p></div></section>`;}
function deploymentResult(){
  if(state.deploymentLoading)return `<div class="empty-state">Verifying the pinned deployment against Koios Preview…</div>`;
  if(state.deploymentError)return `<div class="validation" role="alert">${esc(state.deploymentError)}</div><p class="fine-print">Nothing is shown as verified from a cache or snapshot. Inspect the pinned configuration at its source, or try the live check again.</p>`;
  const d=state.deployment;
  if(!d)return `<div class="simulation-empty">${icon('shield')}<strong>Not verified yet in this session.</strong><span>Run the check to confirm the pinned deployment transaction is confirmed on Preview.</span></div>`;
  return `<div class="asset-data"><h3>Deployment confirmed on Preview</h3><dl><dt>Deployment transaction</dt><dd class="mono">${esc(d.txHash)}</dd><dt>Block · epoch</dt><dd>${fmt(d.blockHeight)} · ${d.epoch}</dd><dt>Confirmed at</dt><dd>${esc(new Date(d.timestamp).toLocaleString())}</dd><dt>Contract execution</dt><dd>Reported valid by Koios</dd><dt>Programmable-logic base script hash</dt><dd class="mono">${esc(d.scriptHash)}</dd><dt>Protocol policy ID</dt><dd class="mono">${esc(d.protocolPolicy)}</dd></dl><p class="fine-print">Checked live at ${esc(new Date(d.fetchedAt).toLocaleTimeString())}: Koios Preview for the transaction, the Foundation platform repository for the pinned configuration, cross-checked field by field. ${external(`${NETWORKS.preview.explorer}/transaction/${d.txHash}`,'View on Cardanoscan Preview','text-link')} ${external(d.source,'Pinned configuration source','text-link')}</p></div>`;
}
function fingerprintPreview(policy,name){
  const p=(policy??'').trim(),n=(name??'').trim();
  if(!p&&!n)return `<p class="fine-print">Enter a policy ID and the fingerprint is computed locally (CIP-14) as you type — no network needed, and the Koios result below is cross-checked against it.</p>`;
  try{const fp=assetFingerprint(p,n);return `<span class="mini-label">ASSET FINGERPRINT · CIP-14 · COMPUTED LOCALLY</span><code class="break-address">${esc(fp)}</code><p class="fine-print">Blake2b-160 of the policy ID and asset name, Bech32-encoded in this browser. It identifies the asset; it does not prove authenticity, backing, or registry membership.</p>`;}
  catch(e){return `<p class="fine-print">${esc(e.message)} The fingerprint appears once the policy ID and asset name are valid hex.</p>`;}
}
function inspectResultView(info){
  const cred=c=>c?`${c.credential==='script'?'Script hash':'Key hash'} · <span class="mono">${esc(c.hash)}</span>`:'None — enterprise addresses carry no stake credential';
  const shape=info.smartWalletShape
    ?`<div class="status-box good">${icon('check')}<span><strong>Matches the CIP-113 smart-wallet shape</strong><small>Payment credential is a script hash (the candidate shared base script) and the stake-position credential — the owner's original payment credential — is <span class="mono">${esc(info.ownerCredential)}</span>. Shape alone does not prove CIP-113 membership: that requires the payment hash to equal a deployed base script hash and the token to appear in that deployment's registry.</small></span></div>`
    :`<div class="notice">${icon('info')}<span><strong>Not a CIP-113 smart-wallet shape.</strong> A smart-wallet address is a base address whose payment credential is the shared base script hash. ${info.kind==='Enterprise'?'This is an enterprise address with no stake credential to carry the owner.':'This address has a key-hash payment credential, so no script gates its spending.'}</span></div>`;
  return `<div class="asset-data"><h3>${esc(info.kind)} address · ${esc(info.networkName)} · header type ${info.type}</h3><dl><dt>Payment credential</dt><dd>${cred(info.payment)}</dd><dt>Stake credential</dt><dd>${cred(info.stake)}</dd><dt>Decoded length</dt><dd>${info.byteLength} bytes (CIP-19)</dd></dl>${shape}<p class="fine-print">Decoded locally from the Bech32 string — checksum verified, nothing was looked up on chain and no balance, registry membership, or deployment is implied.</p></div>`;
}
function renderNetworkData(){
  if(!$('#network-metrics'))return;
  const t=state.tip,age=t?Math.max(0,Math.floor((Date.now()-t.time)/60000)):null,stale=t&&age>5;
  $('#chain-status').innerHTML=state.tipError?`<span class="source-indicator offline"></span><strong>Network data unavailable</strong><span>${esc(state.tipError)}</span>`:t?`<span class="source-indicator ${stale?'stale':''}"></span><strong>${stale?'Delayed chain data':'Live source connected'}</strong><span>Koios · ${NETWORKS[state.network].name} · checked ${new Date(t.fetchedAt).toLocaleTimeString()} · block ${age}m ago</span>`:`<span class="source-indicator stale"></span><strong>Loading ${NETWORKS[state.network].name}</strong><span>Reading the public Koios API…</span>`;
  $('#network-metrics').innerHTML=[['Chain tip',t?fmt(t.block):'—','Latest reported block','layers'],['Current epoch',t?String(t.epoch):'—','From the selected network','globe'],['Absolute slot',t?fmt(t.slot):'—','From the reported chain tip','chart'],['Environment',NETWORKS[state.network].name,state.network==='mainnet'?'Production chain · read only':'Test network · read only','shield']].map(([label,value,hint,ic])=>`<div class="panel network-metric"><span>${label}${icon(ic)}</span><strong>${value}</strong><small>${hint}</small></div>`).join('');
}
async function refreshTip(){const network=state.network,id=++state.requestId;state.tip=null;state.tipError='';renderNetworkData();try{const t=await getChainTip(network);if(state.network!==network||id!==state.requestId)return;state.tip=t;}catch(e){if(state.network!==network||id!==state.requestId)return;state.tipError=e.name==='TimeoutError'?'The source timed out. Please retry.':'Could not reach Koios. No sample data is substituted.';}renderNetworkData();}

function learn(){
  const s=CIP113_STATUS,progress=criteriaProgress();
  return `${header('LEARN CIP-113 · PLAIN LANGUAGE','Tokens that follow <span class="accent-text">rules.</span>','Six short lessons paraphrased from the official specification — each names the spec section it comes from, so you can verify every claim at the source.',external(SPEC_URL,'Read the spec','btn secondary'))}<section class="panel status-tracker" aria-label="CIP-113 status tracker"><div class="panel-heading"><div><h2>Standard status tracker</h2><p>Frontmatter and “Path to Active” checklist, reproduced from the official spec.</p></div>${pill(`STATUS · ${s.status.toUpperCase()}`,'amber')}</div><div class="panel-content"><div class="status-facts"><div><span>Specification status</span><strong>${esc(s.status)}</strong></div><div><span>Merged into CIPs repo</span><strong>${esc(s.merged)}</strong></div><div><span>Spec version</span><strong>${esc(s.specVersion)} (current)</strong></div><div><span>Category · solves</span><strong>${esc(s.category)} · ${esc(s.solves)}</strong></div><div><span>Snapshot verified</span><strong>${esc(s.checked)}</strong></div><div><span>Acceptance criteria met</span><strong>${progress.met} of ${progress.total} (per spec)</strong></div></div><p class="fine-print">Merged ≠ Active ≠ deployed. A CIP becomes Active only when its own Path to Active criteria are met and the authors open a status-change pull request that CIP editors accept (${external(PROCESS_URL,'CIP-0001 process','text-link')}). PRISM re-checks the upstream frontmatter before changing this panel; the date above is the last verification.</p><h3 class="tracker-subhead">Path to Active — acceptance criteria (spec checkboxes)</h3><div class="criteria-list">${ACCEPTANCE_CRITERIA.map(c=>`<div class="criterion"><span class="criterion-box ${c.specChecked?'checked':''}" aria-hidden="true">${c.specChecked?icon('check'):''}</span><div><strong>${esc(c.label)}</strong><small>${esc(c.note)}</small></div><span class="criterion-state">${c.specChecked?'MET':'NOT MET'}</span></div>`).join('')}</div><h3 class="tracker-subhead">Implementation plan (spec)</h3><div class="criteria-list">${IMPLEMENTATION_PLAN.map(i=>`<div class="criterion"><span class="criterion-box plan" aria-hidden="true">${icon('code')}</span><div><strong>${esc(i.label)}</strong><small>${esc(i.note)}</small></div><span class="criterion-state plan">${esc(i.state.toUpperCase())}</span></div>`).join('')}</div><div class="notice tracker-caveat">${icon('info')}<span><strong>Reference implementation caveat:</strong> the Cardano Foundation’s reference implementation and platform describe themselves as research &amp; development — not production-ready, with an independent security audit pending. Nothing on this page changes that.</span></div></div></section><div class="section-heading sources-title"><h2>The learning path</h2><span>Read top to bottom · about five minutes</span></div><div class="learn-path">${LEARNING_PATH.map((l,i)=>`<article class="panel lesson"><div class="lesson-num" aria-hidden="true">${String(i+1).padStart(2,'0')}</div><div class="lesson-body"><h3>${esc(l.title)}</h3><p>${esc(l.plain)}</p><p class="lesson-detail">${esc(l.detail)}</p><span class="lesson-source">Spec section: ${esc(l.specSection)} · ${external(SPEC_URL,'CIP-113','text-link')}</span></div></article>`).join('')}</div><section class="panel learn-cta"><div><h2>Now try the rules yourself</h2><p>The Token studio models these concepts locally — substandards, pauses, allowlists — with no wallet, no funds, and no transactions.</p></div><a class="btn primary" href="#studio">${icon('grid')} Open the Token studio</a></section>`;
}

function guide(){return `${header('OPEN TO EVERY BUILDER','Build the next possibility.','Understand the architecture, inspect the sources, and turn a design into reviewed code.',external(CONFIG.github,`${icon('github')} View repository`,'btn secondary'))}<div class="guide-intro"><div><h2>A useful standard.<br>A deliberate implementation.</h2><p>CIP-113 describes token-like assets that require successful script execution to change owners. PRISM helps explore that model; deployment still requires a complete, tested implementation.</p><a href="#learn" class="text-link">New to CIP-113? Start with the plain-language learning path ${icon('book')}</a></div><div class="status-list"><div><span>Specification status</span>${pill('Proposed','amber')}</div><div><span>PRISM release</span>${pill('Design & research tools')}</div><div><span>Contract deployment</span><strong>Not included</strong></div><div><span>Sources reviewed</span><strong>${CONFIG.verified}</strong></div></div></div><section class="panel"><div class="panel-heading"><h2>Three layers, one transfer model</h2>${icon('layers')}</div><div class="path-grid"><div><span>LAYER 01</span><h3>Registry</h3><p>A linked list records token policy configuration. Applications use registry membership and non-membership proofs to discover the applicable rules.</p></div><div><span>LAYER 02</span><h3>Shared framework</h3><p>The base spending script reads protocol parameters. A global dispatcher requires the delegate for the action, which performs validation.</p></div><div><span>LAYER 03</span><h3>Token-specific logic</h3><p>Issuance, transfer, third-party, and unfracking hooks define the token’s behavior. A design manifest does not implement these validators.</p></div></div></section><section class="panel substandards-guide"><div class="panel-heading"><h2>Reference substandard modules</h2>${pill('FOUNDATION PLATFORM')}</div><div class="path-grid"><div><span>MODULE 01</span><h3>Freeze-and-seize</h3><p>Denylist-aware transfers for regulated tokens. Sender and recipient are checked against an on-chain denylist of credentials; authorised issuers can freeze or seize tokens held by a denylisted holder.</p></div><div><span>MODULE 02</span><h3>KYC</h3><p>Sender certificates. Each transfer carries a short-lived certificate from a trusted KYC entity; the validator checks the signer, the signature, the sender binding, the expiry, and the pause flag. Recipients are not checked.</p></div><div><span>MODULE 03</span><h3>KYC extended</h3><p>Basic KYC plus a recipient allowlist, anchored on chain by a Merkle Patricia Forestry root fingerprint. Entries expire, removals propagate as the root is republished, and self-transfers skip the recipient check.</p></div></div><div class="integration-links"><span class="fine-print">The Token studio models all three locally, check by check — no module is deployed by this site. The Foundation reference platform is R&D, not production-ready, with an independent security audit pending.</span>${external(CONFIG.platform,'Programmable Tokens Platform','text-link')}</div></section><section class="build-checklist panel"><div class="panel-heading"><h2>From design to a deployed token</h2>${pill('DEVELOPER HANDOFF')}</div><div class="build-steps">${[
  ['Export your design','Use the studio to agree on ownership rules, issuer powers, amount precision, and failure cases. The exported format belongs to PRISM.'],
  ['Choose and pin a reference','Start from the Foundation’s core validators and platform. Pin commits and confirm that the SDK, blueprint, and deployment schema agree.'],
  ['Implement the token logic','Build the issuance and transfer hooks. Test denial paths, supply accounting, administrative powers, expired credentials, and script upgrades.'],
  ['Connect trusted services','Run the off-chain backend and indexer. A Midnight integration also needs a deployed circuit, proof service, and an explicit Cardano attestation verifier.'],
  ['Validate on a test network','Review smart-wallet derivation, protocol parameters, registry entries, minting, transfers, recovery paths, and wallet transaction previews.'],
  ['Review before production','Obtain an independent security review and assess the asset’s off-chain obligations. Mainnet readiness cannot be established by this studio.'],
].map(([title,description],i)=>`<div><span class="step-number">${String(i+1).padStart(2,'0')}</span><div><h3>${title}</h3><p>${description}</p></div></div>`).join('')}</div></section><div class="section-heading sources-title"><h2>Built on primary sources</h2><span>Go straight to the people building it</span></div><div class="source-grid">${SOURCES.map(s=>`<a class="panel source-card" href="${s.href}" target="_blank" rel="noopener noreferrer"><span class="source-card-top">${icon(s.icon)}<small>${s.label}</small>${icon('external')}</span><h3>${s.name}</h3><p>${s.description}</p></a>`).join('')}</div><section class="community-panel"><div><span class="eyebrow">BUILT IN THE OPEN</span><h2>Cardano gets better when we build together.</h2><p>Share an idea, report a bug, or contribute a new test case. Follow the journey with @${CONFIG.x}.</p></div><div class="button-row"><button class="btn primary" data-action="share">${icon('share')} Share with the community</button>${external(`https://x.com/${CONFIG.x}`,`${icon('x')} Follow KShot`,'btn secondary')}<button class="text-button" data-action="donate">Support with ADA ${icon('heart')}</button></div></section>`;}

let modalInvoker=null;
function openModal(title,body){const dialog=$('#modal');if(!dialog.open)modalInvoker=captureInvoker(document);dialog.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!dialog.open)dialog.showModal();focusFirst(dialog);}
function walletModal(kind='cardano'){
  const wallets=kind==='cardano'?cardanoWallets():midnightWallets();const connected=kind==='cardano'?state.wallet:state.midnight;
  openModal(kind==='cardano'?'Connect to Cardano':'Connect to Midnight',`<p>Choose an installed wallet. PRISM requests read-only account information. No transaction or message signing is requested.</p>${pill(`${NETWORKS[state.network].name}${state.network==='mainnet'?'':' testnet'}`,kind==='midnight'?'purple':'')}<div class="wallet-options">${wallets.length?wallets.map((w,i)=>`<button class="wallet-option" data-connect="${kind}" data-wallet-index="${i}">${icon(kind==='cardano'?'wallet':'moon')}<strong>${esc(w.name)}</strong><span>Connect ${icon('chevron')}</span></button>`).join(''):`<div class="empty-state">${icon('wallet')}<h3>No compatible wallet detected</h3><p>${kind==='cardano'?'Open PRISM in a desktop browser with a CIP-30 wallet such as Lace or Eternl.':'Use a Midnight wallet that supports DApp Connector API v4. Older connector versions are not supported.'}</p>${external(kind==='cardano'?'https://www.lace.io/':'https://docs.midnight.network/guides/connect-wallet',kind==='cardano'?'Visit Lace':'Midnight wallet documentation','text-link')}</div>`}</div><div id="wallet-error" class="validation" role="status"></div>${kind==='cardano'&&state.network!=='mainnet'?'<p class="fine-print">CIP-30 cannot distinguish Preview from Preprod. Confirm the exact test network in your wallet settings.</p>':''}${connected?`<div class="connected-details"><strong>Currently connected: ${esc(connected.name)}</strong><code class="break-address">${esc(connected.address)}</code><button class="btn secondary full" data-action="disconnect-${kind}">Disconnect from PRISM</button><p class="fine-print">To revoke wallet permission entirely, remove PRISM from your wallet’s connected apps.</p></div>`:''}`);
}
function donationModal(){openModal('Keep the possibilities growing.',`<p>Support KShot’s independent Cardano tools with an optional ADA donation.</p><div class="donation-network">${pill('CARDANO MAINNET')}<span>Send only ADA on Cardano.</span></div><div class="donation-qr"><img src="./donation-qr.svg" alt="QR code of KShot’s Cardano donation address" width="208" height="208"></div><label class="field"><span>KShot’s donation address</span><textarea id="donation-address" rows="4" readonly spellcheck="false">${CONFIG.donation}</textarea></label><button class="btn primary full" data-action="copy-donation">${icon('copy')} Copy donation address</button><p class="fine-print">Use your wallet to review the address and amount. PRISM does not initiate a payment.</p>${external(`https://cardanoscan.io/address/${CONFIG.donation}`,'View address on Cardanoscan','text-link')}`);}
function shareModal(){const text=`Meet PRISM: an open-source Cardano CIP-113 studio. Design token rules, test transfers, explore RealFi scenarios, and connect Midnight. Built by @${CONFIG.x}. Feedback welcome! #Cardano #CIP113 #Midnight`;const url=CONFIG.site;openModal('Built for Cardano. Shared with Cardano.',`<p>Invite the community to try the studio and contribute. The post accurately describes this release as a design workspace.</p><div class="share-preview">${esc(text)}<br><br>${external(url,esc(url),'text-link')}</div><div class="button-row">${external(`https://x.com/intent/post?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`,`${icon('x')} Share on X`,'btn primary')}<button class="btn secondary" data-action="copy-launch">${icon('copy')} Copy launch post</button></div><p class="fine-print">The X button opens a draft. You choose when to publish it.</p>`);}
function download(content,name,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{openModal('Copy this text',`<p>Clipboard access is unavailable. Select and copy the text below.</p><textarea class="copy-fallback" rows="6" readonly>${esc(text)}</textarea>`);$('.copy-fallback').select();}}
function setTab(tab){if(!['design','test','export'].includes(tab))return;state.tab=tab;render();$(`#tab-${tab}`).focus();}

document.addEventListener('click',async event=>{
  const target=event.target.closest('button,[data-action]');if(!target)return;
  if(target.dataset.template){state.design=fromTemplate(target.dataset.template);state.simulation=null;state.seqResult=null;state.subPreset=null;state.subResult=null;state.seizureResult=null;state.seqMode='preset';state.seqCustom=null;state.tab='design';save();render();return;}
  if(target.dataset.seqPreset){state.seqPreset=target.dataset.seqPreset;state.seqMode='preset';state.seqResult=null;render();return;}
  if(target.dataset.seqMove!==undefined&&target.dataset.seqIndex!==undefined){try{state.seqCustom=moveSequenceStep(customSteps(),Number(target.dataset.seqIndex),Number(target.dataset.seqMove));state.seqResult=null;render();}catch(e){toast(e.message,true);}return;}
  if(target.dataset.seqRemove!==undefined){try{state.seqCustom=removeSequenceStep(customSteps(),Number(target.dataset.seqRemove));state.seqResult=null;render();}catch(e){toast(e.message,true);}return;}
  if(target.dataset.subPreset){state.subPreset=target.dataset.subPreset;state.subResult=null;render();return;}
  if(target.dataset.seizurePreset){state.seizurePreset=target.dataset.seizurePreset;state.seizureResult=null;render();return;}
  if(target.dataset.tab){setTab(target.dataset.tab);return;}
  if(target.dataset.connect){
    const kind=target.dataset.connect,network=state.network,list=kind==='cardano'?cardanoWallets():midnightWallets(),entry=list[Number(target.dataset.walletIndex)];if(!entry)return;
    target.disabled=true;target.classList.add('loading');
    try{const connected=kind==='cardano'?await connectCardano(entry.provider,network):await connectMidnight(entry.provider,network);if(network!==state.network)throw new Error('Network changed. Connect again.');if(kind==='cardano')state.wallet=connected;else state.midnight=connected;$('#modal').close();updateWalletButton();render();toast(`${entry.name} connected. Read-only access.`);}catch(e){const msg=e?.info??e?.message??'Wallet connection was declined.';if($('#wallet-error'))$('#wallet-error').textContent=msg;else toast(msg,true);}finally{target.disabled=false;target.classList.remove('loading');}return;
  }
  const action=target.dataset.action;
  switch(action){
    case 'menu':document.body.classList.toggle('menu-open');$('.mobile-menu').setAttribute('aria-expanded',String(document.body.classList.contains('menu-open')));updateNavAccess();break;
    case 'wallet':walletModal();break;
    case 'midnight-wallet':walletModal('midnight');break;
    case 'disconnect-cardano':state.wallet=null;$('#modal').close();updateWalletButton();render();toast('Wallet disconnected from PRISM.');break;
    case 'disconnect-midnight':state.midnight=null;$('#modal').close();render();toast('Midnight disconnected from PRISM.');break;
    case 'close-modal':$('#modal').close();break;
    case 'donate':donationModal();break;
    case 'share':shareModal();break;
    case 'copy-donation':await copy(CONFIG.donation);break;
    case 'copy-launch':await copy(`Explore PRISM, my open-source Cardano CIP-113 design studio: token rules, transfer simulations, RealFi scenarios, and Midnight wallet connectivity. Feedback and contributors welcome! @${CONFIG.x} #Cardano #CIP113 #Midnight\n${CONFIG.site}`);break;
    case 'copy-manifest':if(validateDesign(state.design).length)toast('Fix the design before copying.',true);else await copy(manifestText());break;
    case 'copy-registry-preview':if(validateDesign(state.design).length)toast('Fix the design before copying.',true);else await copy(registryPreviewText());break;
    case 'export-registry-preview':try{download(JSON.stringify(registryDatumPreview(state.design,state.network),null,2),`${state.design.ticker.toLowerCase()}-registry-preview.json`);toast('Registry preview exported. Nothing has been registered.');}catch(e){toast(e.message,true);}break;
    case 'export':try{download(JSON.stringify(makeManifest(state.design,state.network),null,2),`${state.design.ticker.toLowerCase()}-prism-design.json`);toast('Design exported. No tokens have been issued.');}catch(e){toast(e.message,true);}break;
    case 'import':$('#import-file').click();break;
    case 'reset':openModal('Reset this design?',`<p>Your current draft will be replaced with the selected template. Export it first if you want to keep a copy.</p><button class="btn primary full" data-action="confirm-reset">Reset design</button>`);break;
    case 'confirm-reset':state.design=fromTemplate(state.design.template);state.simulation=null;state.seqResult=null;state.subPreset=null;state.subResult=null;state.seizureResult=null;state.seqMode='preset';state.seqCustom=null;save();$('#modal').close();render();toast('Template restored.');break;
    case 'simulate':state.scenario={amount:$('#test-amount').value,recipient:$('#test-recipient').value};state.simulation=simulateTransfer(state.design,state.scenario);$('#simulation-result').innerHTML=simulationResult();break;
    case 'seq-simulate':{try{state.seqResult=simulateTransferSequence(state.design,seqSteps());$('#seq-result').innerHTML=seqResultView();}catch(e){toast(e.message,true);}break;}
    case 'seq-customize':state.seqMode='custom';customSteps();state.seqResult=null;render();break;
    case 'seq-add':try{state.seqCustom=addSequenceStep(customSteps());state.seqResult=null;render();}catch(e){toast(e.message,true);}break;
    case 'sub-simulate':{const p=currentSubPreset();if(!p)break;try{state.subResult=simulateSubstandardTransfer(state.design.substandard,p.scenario);$('#sub-result').innerHTML=subResult();}catch(e){toast(e.message,true);}break;}
    case 'seizure-simulate':{const p=SEIZURE_PRESETS.find(x=>x.id===state.seizurePreset)??SEIZURE_PRESETS[0];state.seizureResult=simulateSeizure(p.scenario);$('#seizure-result').innerHTML=seizureResult();break;}
    case 'credit-template':state.design=fromTemplate('credit');state.tab='design';state.simulation=null;state.seqResult=null;state.subPreset=null;state.subResult=null;state.seizureResult=null;state.seqMode='preset';state.seqCustom=null;save();location.hash='studio';toast('Private credit template loaded. Scenario amounts stay in the lab.');break;
    case 'eligibility':try{state.eligibilityResult=checkEligibility(state.eligibility);$('#eligibility-result').innerHTML=eligibilityResult();}catch(e){toast(e.message,true);}break;
    case 'refresh-network':await refreshTip();break;
    case 'load-reference':{
      const network=state.network;target.disabled=true;
      try{const r=await getReference();if(network!==state.network||!$('#base-script'))return;state.reference=r;$('#base-script').value=r.scriptHash;$('#reference-status').innerHTML=`Fetched Foundation Preview reference at ${new Date().toLocaleTimeString()}. ${external(r.source,'Inspect source','text-link')} This is repository configuration, not a live deployment verification.`;}
      catch{if(network===state.network&&$('#base-script')){$('#base-script').value=PREVIEW_REFERENCE.scriptHash;$('#reference-status').innerHTML=`Live source unavailable. Using the reference snapshot checked ${PREVIEW_REFERENCE.observed}. ${external(PREVIEW_REFERENCE.source,'Inspect source','text-link')} Verify deployment before use.`;}}finally{target.disabled=false;}break;
    }
    case 'copy-derived':if($('#derived-address'))await copy($('#derived-address').textContent);break;
    case 'verify-deployment':{
      state.deploymentLoading=true;state.deploymentError='';state.deployment=null;target.disabled=true;if($('#deployment-results'))$('#deployment-results').innerHTML=deploymentResult();
      try{state.deployment=await getPreviewDeployment();}catch(e){state.deploymentError=e?.message??'Deployment verification failed.';}
      state.deploymentLoading=false;if($('#deployment-results'))$('#deployment-results').innerHTML=deploymentResult();target.disabled=false;break;
    }
    case 'registry':target.disabled=true;try{const rows=await getRegistry();if($('#registry-results'))$('#registry-results').innerHTML=rows.length?rows.map(r=>`<div class="registry-row"><strong>Protocol ${r.protocolParamsId}</strong><code>${esc(r.registryNodePolicyId)}</code><span>${r.tokenCount} indexed tokens</span></div>`).join(''):'<p>The indexer reports no deployments.</p>';}catch(e){toast(e.message,true);}finally{target.disabled=false;}break;
  }
});
document.addEventListener('input',event=>{
  const el=event.target;
  if((el.id==='asset-policy'||el.id==='asset-name')&&$('#asset-fingerprint')){$('#asset-fingerprint').innerHTML=fingerprintPreview($('#asset-policy').value,$('#asset-name').value);return;}
  if(el.dataset.seqField){try{state.seqCustom=updateSequenceStep(customSteps(),Number(el.dataset.seqIndex),{[el.dataset.seqField]:el.value});}catch{/* The editor only offers modeled accounts; an amount stays a string and the simulator reports an unrepresentable one as a blocked step. */}state.seqResult=null;if($('#seq-result'))$('#seq-result').innerHTML=seqResultView();return;}
  if(el.dataset.design){let value=el.type==='checkbox'?el.checked:el.value;if(el.dataset.design==='decimals')value=Number(value);if(el.dataset.design==='ticker'){value=value.toUpperCase();el.value=value;}state.design[el.dataset.design]=value;state.simulation=null;state.seqResult=null;if(el.dataset.design==='substandard'){state.subPreset=null;state.subResult=null;state.seizureResult=null;}save();renderPreview();}
  if(el.dataset.credit){state.credit[el.dataset.credit]=el.value===''?NaN:Number(el.value);updateCredit();}
  if(el.dataset.eligibility){state.eligibility[el.dataset.eligibility]=el.type==='checkbox'?el.checked:el.value===''?NaN:Number(el.value);state.eligibilityResult=null;$('#eligibility-result').innerHTML=eligibilityResult();}
  if(el.id==='test-paused'){state.design.paused=el.checked;state.simulation=null;state.seqResult=null;save();$('#simulation-result').innerHTML=simulationResult();if($('#seq-result'))$('#seq-result').innerHTML=seqResultView();}
  if(['test-amount','test-recipient'].includes(el.id)){state.simulation=null;state.scenario={amount:$('#test-amount').value,recipient:$('#test-recipient').value};$('#simulation-result').innerHTML=simulationResult();}
});
document.addEventListener('change',async event=>{
  const el=event.target;
  if(el.id==='network-select'){state.network=el.value;state.wallet=null;state.midnight=null;state.asset=null;state.reference=null;state.tip=null;state.requestId++;save();updateWalletButton();render();refreshTip();toast(`Switched to ${NETWORKS[state.network].name}. Reconnect wallets for this network.`);}
  if(el.id==='import-file'&&el.files[0]){try{if(el.files[0].size>100000)throw new Error('Choose a file smaller than 100 KB.');const loaded=parseManifest(await el.files[0].text());state.design=loaded.design;if(state.network!==loaded.network){state.wallet=null;state.midnight=null;state.network=loaded.network;state.tip=null;state.requestId++;$('#network-select').value=state.network;updateWalletButton();refreshTip();}state.simulation=null;state.seqResult=null;state.subPreset=null;state.subResult=null;state.seizureResult=null;state.seqMode='preset';state.seqCustom=null;state.tab='design';save();if(location.hash!=='#studio')location.hash='studio';else render();toast('Design imported successfully.');}catch(e){toast(`Import failed: ${e.message}`,true);}el.value='';}
});
document.addEventListener('submit',async event=>{
  if(event.target.id==='derive-form'){event.preventDefault();try{const address=deriveSmartWallet($('#owner-address').value.trim(),$('#base-script').value.trim(),NETWORKS[state.network].id);$('#derived-result').innerHTML=`<div class="derived-box"><span class="mini-label">DERIVED ADDRESS · ${NETWORKS[state.network].name.toUpperCase()}</span><code id="derived-address" class="break-address">${esc(address)}</code><button class="btn secondary compact" data-action="copy-derived" type="button">${icon('copy')} Copy address</button><p class="fine-print">No deployment, funding, or on-chain validation was performed.</p></div>`+inspectResultView(inspectAddress(address));}catch(e){$('#derived-result').innerHTML=`<div class="validation" role="alert">${esc(e.message)}</div>`;}}
  if(event.target.id==='inspect-form'){event.preventDefault();try{const info=inspectAddress($('#inspect-address').value.trim());$('#inspect-result').innerHTML=inspectResultView(info);}catch(e){$('#inspect-result').innerHTML=`<div class="validation" role="alert">${esc(e.message)}</div>`;}}
  if(event.target.id==='asset-form'){event.preventDefault();const network=state.network,button=$('#asset-submit'),result=$('#asset-result');const policy=$('#asset-policy').value.trim(),nameHex=$('#asset-name').value.trim();let localFp='';try{localFp=assetFingerprint(policy,nameHex);}catch(e){result.innerHTML=`<div class="validation" role="alert">${esc(e.message)}</div>`;return;}button.disabled=true;result.innerHTML='<div class="empty-state">Reading asset data…</div>';try{const data=await queryAsset(network,policy,nameHex);if(network!==state.network||!result.isConnected)return;const cross=!data?'':!data.fingerprint?`<div class="notice">${icon('info')}<span>Koios did not return a fingerprint for this asset, so there is nothing to cross-check — the fingerprint below is the local CIP-14 computation only.</span></div>`:data.fingerprint===localFp?`<div class="status-box good">${icon('check')}<span><strong>Koios fingerprint matches the local CIP-14 computation</strong><small>Two independent paths agree on this asset's identity: the live source and a Blake2b-160 computed in this browser from the policy ID and asset name you entered.</small></span></div>`:`<div class="status-box bad">${icon('close')}<span><strong>Koios returned a different fingerprint — do not rely on this result</strong><small>Koios reported <span class="mono">${esc(data.fingerprint)}</span> but the local CIP-14 computation from the identifiers you entered is <span class="mono">${esc(localFp)}</span>. One of the two does not describe the asset you asked for.</small></span></div>`;result.innerHTML=data?`<div class="asset-data"><h3>Asset found on ${NETWORKS[network].name}</h3><dl><dt>Fingerprint (CIP-14, computed locally)</dt><dd class="mono">${esc(localFp)}</dd><dt>Total supply (base units)</dt><dd>${esc(data.total_supply??'Not returned')}</dd><dt>Decimals</dt><dd>${esc(data.token_registry_metadata?.decimals??'Not provided')}</dd></dl>${cross}<p class="fine-print">Live response from Koios at ${new Date().toLocaleTimeString()}. Registry status is not inferred.</p></div>`:'<div class="empty-state">No matching asset was returned on this network.</div>';}catch(e){if(network===state.network&&result.isConnected)result.innerHTML=`<div class="validation" role="alert">${esc(e.message??'Asset query failed.')}</div><p class="fine-print">The lookup failed, but the fingerprint is local: <span class="mono">${esc(localFp)}</span> — computed from the identifiers alone, it needs no network.</p>`;}finally{button.disabled=false;}}
});
document.addEventListener('keydown',event=>{
  if(event.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const keys=['design','test','export'],i=keys.indexOf(state.tab);setTab(event.key==='Home'?'design':event.key==='End'?'export':keys[(i+(event.key==='ArrowRight'?1:2))%3]);}
  if(event.key==='Escape'){document.body.classList.remove('menu-open');$('.mobile-menu').setAttribute('aria-expanded','false');updateNavAccess();}
});
function updateNavAccess(){const side=$('#sidebar');if(side)side.inert=matchMedia('(max-width:800px)').matches&&!document.body.classList.contains('menu-open');}
matchMedia('(max-width:800px)').addEventListener('change',updateNavAccess);
function updateWalletButton(){const el=$('#wallet-button');el.innerHTML=`${icon('wallet')}<span>${state.wallet?esc(short(state.wallet.address,6)):'Connect wallet'}</span>`;el.classList.toggle('connected',!!state.wallet);}
async function checkWallet(){if(state.wallet)try{await refreshCardano(state.wallet,state.network);}catch(e){state.wallet=null;updateWalletButton();toast(e.message,true);}if(state.midnight)try{await refreshMidnight(state.midnight,state.network);}catch(e){state.midnight=null;if(state.route==='midnight')render();toast(e.message||'Midnight connection changed. Reconnect your wallet.',true);}}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
window.addEventListener('focus',checkWallet);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){checkWallet();if(state.tip&&Date.now()-state.tip.fetchedAt>120000)refreshTip();}});
setInterval(()=>{if(!document.hidden){checkWallet();if(state.route==='network')refreshTip();}},60000);
shell();
$('#modal').addEventListener('close',()=>{const target=modalInvoker;modalInvoker=null;restoreFocus(target);});
$('.skip-link').addEventListener('click',event=>{event.preventDefault();$('#main').focus();$('#main').scrollIntoView();});
render();refreshTip();
